### Objective
Build a production-grade, offline-resilient Product Catalog & Inventory client in Flutter using `package:http`. Demonstrate persistent `http.Client` lifecycle management, defensive JSON deserialization, background isolate offloading via `compute()`, typed network exception hierarchies, and a responsive UI with pull-to-refresh and retry mechanics.

```dart
import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;

void main() {
  runApp(const HttpProductApp());
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. DOMAIN MODELS & DEFENSIVE DESERIALIZATION
// ─────────────────────────────────────────────────────────────────────────────

class Product {
  final String id;
  final String title;
  final String description;
  final double price;
  final double rating;
  final int stock;
  final String category;

  const Product({
    required this.id,
    required this.title,
    required this.description,
    required this.price,
    required this.rating,
    required this.stock,
    required this.category,
  });

  /// Defensive fromJson constructor resilient against schema deviations
  factory Product.fromJson(Map<String, dynamic> json) {
    return Product(
      id: json['id']?.toString() ?? '',
      title: json['title'] as String? ?? 'Untitled Product',
      description: json['description'] as String? ?? '',
      price: (json['price'] as num?)?.toDouble() ?? 0.0,
      rating: (json['rating'] as num?)?.toDouble() ?? 0.0,
      stock: (json['stock'] as num?)?.toInt() ?? 0,
      category: json['category'] as String? ?? 'General',
    );
  }

  Map<String, dynamic> toJson() => {
    'id': id,
    'title': title,
    'description': description,
    'price': price,
    'rating': rating,
    'stock': stock,
    'category': category,
  };
}

/// Standalone top-level function required for compute() background isolate
List<Product> parseProductList(String rawJson) {
  final decoded = jsonDecode(rawJson);
  if (decoded is! List) {
    throw const FormatException('Expected a JSON array of products');
  }
  return decoded
      .map((item) => Product.fromJson(item as Map<String, dynamic>))
      .toList();
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. NETWORK EXCEPTION HIERARCHY
// ─────────────────────────────────────────────────────────────────────────────

sealed class NetworkException implements Exception {
  final String message;
  const NetworkException(this.message);

  @override
  String toString() => message;
}

class NoInternetException extends NetworkException {
  const NoInternetException() : super('No internet connection. Please check your network settings.');
}

class RequestTimeoutException extends NetworkException {
  const RequestTimeoutException() : super('The server took too long to respond. Please try again.');
}

class ServerException extends NetworkException {
  final int statusCode;
  const ServerException(this.statusCode, String message) : super('Server Error ($statusCode): $message');
}

class ParseException extends NetworkException {
  const ParseException(String message) : super('Data parsing error: $message');
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. PRODUCTION API CLIENT & REPOSITORY
// ─────────────────────────────────────────────────────────────────────────────

class ProductApiClient {
  final http.Client _client;
  static const Duration _timeoutDuration = Duration(seconds: 8);

  ProductApiClient({http.Client? client}) : _client = client ?? http.Client();

  Future<List<Product>> fetchProducts() async {
    // Constructing Uri safely with query parameters
    final uri = Uri.https('fakestoreapi.com', '/products', {'limit': '20'});

    try {
      final response = await _client
          .get(
            uri,
            headers: {
              HttpHeaders.acceptHeader: 'application/json',
              HttpHeaders.contentTypeHeader: 'application/json; charset=UTF-8',
              'X-Client-Platform': 'Flutter-Foundation',
            },
          )
          .timeout(_timeoutDuration);

      return _handleResponse(response);
    } on SocketException {
      throw const NoInternetException();
    } on TimeoutException {
      throw const RequestTimeoutException();
    } on FormatException catch (e) {
      throw ParseException(e.message);
    } catch (e) {
      if (e is NetworkException) rethrow;
      throw ParseException(e.toString());
    }
  }

  Future<List<Product>> _handleResponse(http.Response response) async {
    final statusCode = response.statusCode;

    if (statusCode >= 200 && statusCode < 300) {
      // Offload JSON decoding to a background isolate to keep UI butter-smooth!
      return await compute(parseProductList, response.body);
    } else if (statusCode == 401 || statusCode == 403) {
      throw const ServerException(401, 'Unauthorized request. Please log in again.');
    } else if (statusCode == 404) {
      throw const ServerException(404, 'The requested products could not be found.');
    } else if (statusCode >= 500) {
      throw ServerException(statusCode, 'Server experiencing downtime.');
    } else {
      throw ServerException(statusCode, 'Unexpected error occurred.');
    }
  }

  void dispose() {
    _client.close();
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 4. PRESENTATION LAYER
// ─────────────────────────────────────────────────────────────────────────────

class HttpProductApp extends StatelessWidget {
  const HttpProductApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'HTTP Networking Architecture',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.blueAccent,
        useMaterial3: true,
      ),
      home: const ProductCatalogScreen(),
    );
  }
}

class ProductCatalogScreen extends StatefulWidget {
  const ProductCatalogScreen({super.key});

  @override
  State<ProductCatalogScreen> createState() => _ProductCatalogScreenState();
}

class _ProductCatalogScreenState extends State<ProductCatalogScreen> {
  late final ProductApiClient _apiClient;
  late Future<List<Product>> _productsFuture;

  @override
  void initState() {
    super.initState();
    _apiClient = ProductApiClient();
    _refreshProducts();
  }

  void _refreshProducts() {
    setState(() {
      _productsFuture = _apiClient.fetchProducts();
    });
  }

  @override
  void dispose() {
    _apiClient.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Product Catalog (http.Client)'),
        centerTitle: true,
        actions: [
          IconButton(
            icon: const Icon(Icons.refresh_rounded),
            onPressed: _refreshProducts,
            tooltip: 'Reload Catalog',
          ),
        ],
      ),
      body: FutureBuilder<List<Product>>(
        future: _productsFuture,
        builder: (context, snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  CircularProgressIndicator(),
                  SizedBox(height: 16),
                  Text('Fetching products over TLS connection...'),
                ],
              ),
            );
          }

          if (snapshot.hasError) {
            final error = snapshot.error;
            final message = error is NetworkException
                ? error.message
                : 'An unexpected error occurred: $error';

            return Center(
              child: Padding(
                padding: const EdgeInsets.all(24.0),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    const Icon(Icons.cloud_off_rounded, size: 64, color: Colors.redAccent),
                    const SizedBox(height: 16),
                    Text(
                      'Network Error',
                      style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.bold),
                    ),
                    const SizedBox(height: 8),
                    Text(
                      message,
                      textAlign: TextAlign.center,
                      style: const TextStyle(color: Colors.black54),
                    ),
                    const SizedBox(height: 24),
                    FilledButton.icon(
                      onPressed: _refreshProducts,
                      icon: const Icon(Icons.refresh),
                      label: const Text('Retry Connection'),
                    ),
                  ],
                ),
              ),
            );
          }

          final products = snapshot.data ?? [];
          if (products.isEmpty) {
            return const Center(child: Text('No products available.'));
          }

          return RefreshIndicator(
            onRefresh: () async => _refreshProducts(),
            child: ListView.separated(
              padding: const EdgeInsets.all(16),
              itemCount: products.length,
              separatorBuilder: (_, __) => const SizedBox(height: 12),
              itemBuilder: (context, index) {
                final product = products[index];
                return Card(
                  elevation: 1,
                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
                  child: ListTile(
                    contentPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
                    leading: CircleAvatar(
                      backgroundColor: Colors.blue.shade50,
                      child: Text(
                        product.title.isNotEmpty ? product.title[0] : 'P',
                        style: TextStyle(color: Colors.blue.shade800, fontWeight: FontWeight.bold),
                      ),
                    ),
                    title: Text(
                      product.title,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(fontWeight: FontWeight.bold),
                    ),
                    subtitle: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const SizedBox(height: 4),
                        Text(
                          product.category.toUpperCase(),
                          style: TextStyle(fontSize: 10, letterSpacing: 0.8, color: Colors.blue.shade700, fontWeight: FontWeight.bold),
                        ),
                        const SizedBox(height: 4),
                        Text(
                          product.description,
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(fontSize: 12, color: Colors.black54),
                        ),
                      ],
                    ),
                    trailing: Text(
                      '\$${product.price.toStringAsFixed(2)}',
                      style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 16, color: Colors.green),
                    ),
                  ),
                );
              },
            ),
          );
        },
      ),
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **Defensive Model Deserialization**:
   The `Product.fromJson` factory constructor uses safe null-coalescing and type coercion (`(json['price'] as num?)?.toDouble() ?? 0.0`). Even if the remote API emits an integer (`1999`) or null instead of a floating point double, the app will never crash with a `TypeError`.
2. **Dedicated Background Parsing with compute()**:
   `compute(parseProductList, response.body)` invokes `parseProductList` in a brand new worker isolate. The CPU cycles spent parsing strings into JSON maps and allocating `Product` instances happen entirely in parallel to the main UI isolate, maintaining a 60/120 FPS UI frame rate.
3. **Structured Network Exception Hierarchy**:
   A sealed `NetworkException` hierarchy transforms low-level OS exceptions (`SocketException`, `TimeoutException`) into user-comprehensible errors (`NoInternetException`, `RequestTimeoutException`).
4. **Persistent Socket Reuse with http.Client**:
   The `ProductApiClient` owns an `http.Client` instance that persists across requests. Instead of negotiating a new TLS handshake on every call, the socket is kept alive and pooled, significantly reducing network latency.
5. **Clean Resource Cleanup**:
   `ProductApiClient.dispose()` calls `_client.close()`, terminating active socket connections cleanly when the hosting widget or service is destroyed.
